sections.css_fragment:
.ih-scope-unit_1_what_is_few_shot { --ih-accent: #5b6cff; --ih-surface: #ffffff; --ih-text: #1f2937; max-width: 920px; margin: 0 auto; padding: 24px; overflow-wrap: break-word; }}
.ih-scope-unit_1_what_is_few_shot .ih-block { background: var(--ih-surface); border: 1px solid rgba(36,48,68,.12); border-radius: 20px; padding: 22px; margin-bottom: 18px; }}

.ih-scope-unit_1_what_is_few_shot .ih-options { display: grid; gap: 12px; margin: 16px 0; }
.ih-scope-unit_1_what_is_few_shot .ih-option { width: 100%; text-align: left; border: 1px solid rgba(36,48,68,.14); background: #fff; color: var(--ih-text, #243044); border-radius: 16px; padding: 13px 15px; cursor: pointer; display: flex; gap: 10px; align-items: flex-start; }
.ih-scope-unit_1_what_is_few_shot .ih-option::before { content: attr(data-option-label); display: inline-grid; place-items: center; flex: 0 0 28px; width: 28px; height: 28px; border-radius: 999px; background: rgba(92,109,246,.12); color: var(--ih-accent, #5c6df6); font-weight: 800; }
.ih-scope-unit_1_what_is_few_shot .ih-option.is-selected, .ih-scope-unit_1_what_is_few_shot .ih-option.selected, .ih-scope-unit_1_what_is_few_shot .ih-option.active { border-color: var(--ih-accent, #5c6df6); background: rgba(92,109,246,.10); }
.ih-scope-unit_1_what_is_few_shot .ih-option.is-correct { border-color: rgba(22,163,74,.55); background: rgba(22,163,74,.08); }
.ih-scope-unit_1_what_is_few_shot .ih-option.is-wrong { border-color: rgba(220,38,38,.46); background: rgba(220,38,38,.06); }
.ih-scope-unit_1_what_is_few_shot .ih-submit { border: 0; border-radius: 999px; padding: 10px 18px; background: var(--ih-accent, #5c6df6); color: #fff; font-weight: 800; cursor: pointer; }
.ih-scope-unit_1_what_is_few_shot .ih-submit.secondary { background: #243044; }
.ih-scope-unit_1_what_is_few_shot .ih-textarea { width: 100%; min-height: 120px; resize: vertical; border: 1px solid rgba(36,48,68,.14); border-radius: 16px; padding: 14px 16px; background: #fff; color: var(--ih-text, #243044); }
.ih-scope-unit_1_what_is_few_shot .ih-feedback { display: none; margin-top: 14px; border-radius: 16px; padding: 14px 16px; background: rgba(255,255,255,.78); border: 1px solid rgba(36,48,68,.12); }
.ih-scope-unit_1_what_is_few_shot .ih-feedback.is-visible { display: block; }
.ih-scope-unit_1_what_is_few_shot .ih-feedback.success { border-color: rgba(22,163,74,.35); background: rgba(22,163,74,.08); }
.ih-scope-unit_1_what_is_few_shot .ih-feedback.warn { border-color: rgba(255,184,107,.55); background: rgba(255,184,107,.12); }
.ih-scope-unit_1_what_is_few_shot .scenario-box { display: grid; grid-template-columns: minmax(0,.9fr) minmax(0,1.1fr); gap: 16px; }
.ih-scope-unit_1_what_is_few_shot .scenario-card { border-radius: 18px; padding: 18px; background: #243044; color: #fff; }
.ih-scope-unit_1_what_is_few_shot .scenario-card .tag { display: inline-block; background: rgba(255,255,255,.14); border-radius: 999px; padding: 4px 10px; font-size: 12px; margin-bottom: 10px; }
@media (max-width: 760px) { .ih-scope-unit_1_what_is_few_shot .scenario-box { grid-template-columns: 1fr; } }
